Intent: Add a fast path that reserves capacity before early return.

Diff under review:
--- a/src/fabric/admission.ts
+++ b/src/fabric/admission.ts
@@
+export function fastPath(requestId: string, routeId: string) {
+  reserve(requestId, routeId);
+  if (!routeId) return;
+}

